321	        if (item.deliveryInvalidated || ambiguous(item)) { persistInvalidations(); return DeliveryOutcome.Invalidated(item.id) }
322	        if (bypassed(item.id) || unprocessed(item.id)) return DeliveryOutcome.Deferred(item.id)
323	        val time = environment.timeContext()
324	        val schedule = environment.schedule()
325	        val setting = environment.settings()[item.priority] ?: PriorityDeliverySetting.defaultFor(item.priority)
326	        val decision = NotificationDeliveryPolicy.canDeliverNow(item.priority, setting, schedule, time, budget.read())
327	        if (setting.budgetBehavior == BudgetBehavior.RESPECTING && reserved.isNotEmpty()) {
