            legacyRemovals[id] = maxOf(legacyRemovals[id] ?: Long.MIN_VALUE, atMillis)
            if (legacyRemovals.size > eventCapacity) legacyRemovals.remove(legacyRemovals.keys.first())
        }
        gate.run {
