                events[id] = event.copy(removed = true, lastRemoval = clearOrder, appliedRemoval = clearOrder)
            }
        }
    }

    suspend fun clearAll(delete: suspend () -> Unit) {
        invalidateAll()
        gate.run { delete() }
    }

